          max-width: 480px;
          margin: 24px auto;
          padding: 0 16px 32px;
        }
        h1 {
          font-weight: 600;
          font-size: 1.5rem;
          margin-bottom: 16px;
          font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
